}

.modern-table td {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
  word-break: break-word;
}

.modern-table tr:last-child td {
  border-bottom: none;
}

.modern-table tr.row-system {
  background: #fffcf9;
}

.tag-name-cell {
  display: flex;
