  padding-right: 0.5rem;
}

.btn-sort-order {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.25rem;
  border-radius: 50%;
  border: none;
  background: #f1f5f9;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s;
}

.btn-sort-order:hover {
  background: var(--primary);
  color: white;
}

/* === EDIT ORDER MODAL === */
.modal-content-large {
  background: white;
  border-radius: 2rem;
  max-width: 800px;
  width: 95%;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: 0 30px 60px -12px rgba(0, 0, 0, 0.25);
  animation: modalSlideIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  display: flex;
  flex-direction: column;
}

.edit-order-form {
  padding: 2.5rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.form-section {
  background: #f8fafc;
  padding: 1.5rem;
  border-radius: 1.25rem;
  border: 1px solid #e2e8f0;
}

.form-section h4 {
  margin: 0 0 1.25rem 0;
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.form-select {
  width: 100%;
  padding: 1rem;
  border-radius: 0.85rem;
  border: 1px solid #cbd5e1;
  font-family: inherit;
  font-size: 0.95rem;
  cursor: pointer;
  background: white;
}

.order-items-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.edit-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.5rem;
  background: white;
  border-radius: 1rem;
  border: 1px solid #e2e8f0;
  transition: all 0.2s;
}

.edit-item:hover {
  border-color: var(--primary-light);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
}

.item-name {
  font-weight: 600;
  color: var(--text-main);
  flex: 1;
}

.item-controls {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin: 0 1.5rem;
}

.btn-qty {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid #cbd5e1;
  background: white;
  color: var(--text-main);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  transition: all 0.2s;
}

.btn-qty:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}

.qty-input {
  width: 50px;
  text-align: center;
  padding: 0.5rem;
  border: 1px solid #e2e8f0;
  border-radius: 0.5rem;
  font-weight: 700;
  -moz-appearance: textfield;
  appearance: textfield;
}

.qty-input::-webkit-outer-spin-button,
.qty-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  appearance: none;
  margin: 0;
}

.btn-remove-item {
  background: #fef2f2;
  color: #ef4444;
  border: none;
  padding: 0.5rem;
  border-radius: 0.75rem;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn-remove-item:hover {
  background: #fee2e2;
  transform: scale(1.1);
}

.item-price {
  font-weight: 800;
  color: var(--text-main);
  min-width: 90px;
  text-align: right;
}

.order-total-row {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 1.5rem;
  padding-top: 1.5rem;
  margin-top: 1rem;
  border-top: 2px solid #e2e8f0;
}

.total-amount {
  font-size: 1.75rem;
  color: var(--primary);
  letter-spacing: -0.02em;
}

