  }

  .tag-name-cell {
    font-size: 0.85rem;
    max-width: 120px;
    word-break: break-word;
  }

  .table-actions {
    display: flex;
    gap: 0.25rem;
  }

  .btn-icon-action {
    padding: 0.5rem !important;
    font-size: 0.7rem;
    min-width: 36px;
    height: 36px;
  }

  .btn-icon-action span {
